// monetization.js
// Simple, non-extractive monetization helper for HALO / ApockyOS

const KOFI_URL = "https://ko-fi.com/oneinfinity";
const SUPPORTER_FLAG = "halo_supporter";

// Call this once after DOM is ready
export function initMonetization() {
  const btn = document.getElementById("supportButton");
  const badge = document.getElementById("supporterBadge");

  if (btn) {
    btn.addEventListener("click", () => {
      // Open Ko-fi in a new tab
      window.open(KOFI_URL, "_blank", "noopener");

      // Optional: optimistically mark as supporter if they *choose* to
      // You can also wire this to a Ko-fi webhook in a backend later.
      const ok = confirm(
        "Did you just choose to support the project on Ko-fi? " +
          "If yes, I can enable 'supporter mode' (purely cosmetic/QoL perks)."
      );
      if (ok) {
        localStorage.setItem(SUPPORTER_FLAG, "true");
        updateSupporterState(badge);
      }
    });
  }

  updateSupporterState(badge);
}

export function isSupporter() {
  return localStorage.getItem(SUPPORTER_FLAG) === "true";
}

function updateSupporterState(badgeEl) {
  if (!badgeEl) return;
  if (isSupporter()) {
    badgeEl.style.display = "inline-flex";
  } else {
    badgeEl.style.display = "none";
  }
}
```

