export class MonetizationCore {
  private events: SupportEvent[] = [];
  private config: MonetizationConfig;

  constructor(config: MonetizationConfig) {
    this.config = config;
  }

  getConfig() {
    return this.config;
  }

  recordSupport(event: SupportEvent) {
    this.events.push(event);
    // TODO: persist to local DB / cloud
