## 3. Co-op core (sovereign sessions)

This is your “co-op but not hive-mind” backbone.

```ts
// coopCore.ts

export interface PlayerInfo {
  id: string;
  displayName: string;
  avatarUrl?: string;
}

export interface SessionState {
  id: string;
  hostId: string;
  players: PlayerInfo[];
  createdAt: number;
  lastUpdated: number;
  isOpen: boolean;
  metadata?: Record<string, any>; // e.g. rules, seed, element setup
}

export class CoopManager {
  private currentSession: SessionState | null = null;

  createSession(host: PlayerInfo, metadata?: Record<string, any>): SessionState {
    const now = Date.now();
    this.currentSession = {
      id: `sess_${now}_${Math.random().toString(36).slice(2)}`,
      hostId: host.id,
      players: [host],
      createdAt: now,
      lastUpdated: now,
      isOpen: true,
      metadata,
    };
    return this.currentSession;
  }

  joinSession(player: PlayerInfo, session: SessionState): SessionState {
    if (!session.isOpen) throw new Error('Session is closed.');
    const already = session.players.some(p => p.id === player.id);
    if (!already) {
      session.players = [...session.players, player];
      session.lastUpdated = Date.now();
    }
    this.currentSession = session;
    return session;
  }

  leaveSession(playerId: string): SessionState | null {
    if (!this.currentSession) return null;
    this.currentSession.players = this.currentSession.players.filter(p => p.id !== playerId);
    this.currentSession.lastUpdated = Date.now();
    if (this.currentSession.players.length === 0) {
      this.currentSession = null; // dissolve room
    }
    return this.currentSession;
  }

  closeSession() {
    if (this.currentSession) {
      this.currentSession.isOpen = false;
      this.currentSession.lastUpdated = Date.now();
    }
  }

  getSession() {
    return this.currentSession;
  }
}
```

